def solve(node):
  if node is null:
    return BaseCase
  left_result = solve(node.left)
  right_result = solve(node.right)
  return merge(left_result, right_result, node.val)

code.python:
def maxDepth(root):
    if not root:
        return 0
    return max(maxDepth(root.left), maxDepth(root.right)) + 1

code.javascript:
